import sys
p = sys.argv[1]
lines = open(p, encoding='utf-8').read().split('\n')
idx = [i for i, l in enumerate(lines) if l.startswith('| 677 |')]
assert len(idx) == 1
rows = [
"| 678 | 2026-10-26 | **Intervals and Chords Further, the third Grades 2-3 room (Build AL).** Built on row 677. Board call 14, in her order. New chapter `harmony-23` (chapter 32) on the Grades 2-3 floor after Scales Further; Pitch door, Chords topic, group ch-23 after 'Chords in a key'; Stories of music moves to 33-35. Theory of Music Grades 2 and 3 (Manual 2026, read 26 Oct): (1) intervals above the tonic in the harmonic minor, number and quality (H3_MIN: A, E, D minor at Grade 2 treble; G, C minor at Grade 3, treble or bass; the 3rd and 6th minor, the raised 7th major; H3IvPad with distractors H3_DIST); (2) the degree names, tonic to leading note (H3DegPad; Korean 으뜸음 윗으뜸음 가온음 버금딸림음 딸림음 버금가온음 이끎음); (3) the primary triads in close position, root position and first inversion, treble or bass (H3_TRI: C, G, F, D, Bb major, A minor with V raised; H3InvPad on ChordStaff); (4) soprano, alto, tenor, bass on the grand staff (SatbStaff: new component, soprano and tenor stems up, alto and bass down, key signature, range bands; H3_RANGE soprano C4-G5, alto G3-C5, tenor C3-G4, bass E2-C4: the usual textbook ranges, flagged for her, since the syllabus says only 'approximate compass'); (5) the perfect and plagal cadences in four-part vocal style (H3_CAD: C, G, F, D major, A and D minor, every chord spelled by hand: roots in the bass, root doubled, the leading note rising, the common note kept, each pair of voices checked for parallel 5ths and octaves, every voice in range). Drill levels iv (treble), iv (bass), deg, inv, voice, cad; Home h3-iv, h3-deg, h3-inv, h3-satb, h3-cad (KqEngine choice questions built on the drill's generator; HOME_FLOOR '23'); Lesson Book of 7 pages (h3LbPages); teacher's copy H3Teacher with every interval, triad and cadence spelled out. No Workbook yet. Not changed, flagged: the Home's 'Seven chords in a key' and 'Cadences' (imperfect, interrupted) carry Grade 4 Theory of Music content under a {23} mark. Tests al705.js, al705b.js, chsweep, booksweep, reg674. |",
]
for r in reversed(rows): lines.insert(idx[0] + 1, r)
open(p, 'w', encoding='utf-8').write('\n'.join(lines)); print('ok')
